"""Minimal-sync decode loop for Bolmo (batch 1): one device-to-host read per generated byte.

Replaces the decode part of the remote `BolmoForCausalLM.generate()`; the prefill part is
reproduced from it unchanged so the state entering the decode loop is identical. See
notes/bolmo_decode_loop.md for what the original loop does per byte (about 9 host syncs, a
history walk in `expand_byte_ids`, `torch.cat`, two `MaskState`s ...).

Per decoded byte, with `raw` = the token read from the GPU (byte id, +260 if it carries the
fused boundary flag):

  host:  subword id = automaton.step(state, raw)            O(1), no history
         pinned (byte, subword id) -> device                one H2D copy
  GPU:   graph enc  (embedding, 1 layer, norm, out_projection)
         graph glob (16 layers, static KV cache)            only if the previous byte was a boundary
         graph dec  (in_projection, 4 layers, norm, lm_head, argmax)
  host:  token -> pinned memory, event record + synchronize  the single sync
         raw = pinned token; boundary flag = raw >= boundary_offset

State the original loop keeps that does not affect the model and is therefore not reproduced:
`bytes_since_boundary` (written, never read), `MaskState` objects (at batch 1 they reduce to the
host bool `boundary`), `tokens_generated_plus_prefilled`, `bytes_generated`.
"""

from __future__ import annotations

import sys
from typing import Any, Callable

import torch
import torch.nn as nn

from . import OptimizeError
from .subword_automaton import SubwordAutomaton


class MinimalPieces(nn.Module):
    """Extra graphed functions for the minimal loop (reading/writing static buffers)."""

    def __init__(self, model: Any, loop: Any, glob: Any, device: str):
        super().__init__()
        self.model_ref = [model]  # not registered as a submodule
        self.loop, self.glob = loop, glob
        self.register_buffer("ids", torch.zeros(2, dtype=torch.long, device=device), persistent=False)
        self.register_buffer("tok", torch.zeros(1, dtype=torch.long, device=device), persistent=False)

    def enc_m(self) -> None:
        self.loop.byte_ids.copy_(self.ids[:1].view(1, 1))
        self.loop.exp_ids.copy_(self.ids[1:].view(1, 1))
        self.loop.enc_step()

    def _tail(self) -> None:
        m = self.model_ref[0]
        self.loop.dec_step()
        h = m.model.norm(self.loop.dec_out)
        logits = m.lm_head(h[:, -1:, :])
        self.tok.copy_(torch.argmax(logits[:, -1], dim=-1))

    def dec_n(self) -> None:  # no new patch: decoder keeps its last_value
        self._tail()

    def dec_p(self) -> None:  # boundary step: new patch from the global model
        h_patch = self.loop.dec.initial_norm(self.glob.glob_out)[:, -1:, :]
        self.loop.last_value.copy_(h_patch[:, -1])
        self._tail()


def capture_pieces(runner: Any, pieces: MinimalPieces) -> None:
    """Warm up and capture enc_m / dec_n / dec_p next to the graphs the runner already has."""
    torch.cuda.synchronize()
    fns = [("enc_m", pieces.enc_m), ("dec_n", pieces.dec_n), ("dec_p", pieces.dec_p)]
    s = torch.cuda.Stream()
    s.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(s), torch.inference_mode():
        for _ in range(3):
            pieces.glob.step()
            for _, fn in fns:
                fn()
    torch.cuda.current_stream().wait_stream(s)
    torch.cuda.synchronize()
    pieces.glob.pos.zero_()
    for name, fn in fns:
        g = torch.cuda.CUDAGraph()
        with torch.inference_mode(), torch.cuda.graph(g):
            fn()
        runner.graphs[name] = g
    torch.cuda.synchronize()


def make_generate(model: Any, tok: Any, runner: Any, loop: Any, glob: Any, pieces: MinimalPieces,
                  automaton: SubwordAutomaton, *, debug: Callable[[int, dict], None] | None = None) -> Callable:
    """Returns a `generate(inputs, **kwargs)` replacement for batch 1, greedy decoding."""
    mod = sys.modules[type(model).__module__]
    MaskState = mod.MaskState
    bm = model.model
    enc, dec = bm.local_encoder, bm.local_decoder
    tk = bm.tokenizer
    boundary_offset = tk.offset + 256
    eos, pad, bpe_end = tk.eos_token_id, tk.pad_token_id, tk.bpe_token_end_id
    dev = next(model.parameters()).device

    pinned_ids = torch.zeros(2, dtype=torch.long).pin_memory()
    pinned_tok = torch.zeros(1, dtype=torch.long).pin_memory()
    ids_np, tok_np = pinned_ids.numpy(), pinned_tok.numpy()
    done = torch.cuda.Event()

    @torch.no_grad()
    def generate(inputs: torch.Tensor, generation_config: Any = None, logits_processor: Any = None,
                 stopping_criteria: Any = None, use_model_defaults: Any = None, **kwargs: Any) -> torch.Tensor:
        if inputs.shape[0] != 1 or kwargs.get("do_sample"):
            raise OptimizeError("minimal loop supports batch size 1 and greedy decoding only")
        max_new = kwargs.get("max_new_tokens")
        if max_new is None:
            raise OptimizeError("minimal loop needs max_new_tokens")
        prompt_len = inputs.shape[1]
        # Stop when the list of generated atoms reaches this length (it starts with the
        # second-to-last prompt byte): the model's MaxLengthCriteria and the harness's _MaxAtoms.
        stop_len = (prompt_len - 1) + max_new
        for crit in stopping_criteria or []:
            n = getattr(crit, "n", None)
            if n is None:
                raise OptimizeError(f"unsupported stopping criterion {type(crit).__name__}")
            stop_len = min(stop_len, n + 2)

        # ---- prefill: same calls as the remote generate() --------------------------------
        expanded = torch.tensor(tk.expand_byte_ids(inputs[0].tolist()), device=dev, dtype=torch.long)[None]
        byte_input_ids = inputs
        sequence_start_indices = (byte_input_ids == pad).sum(-1)
        enc.free_inference_cache()
        dec.free_inference_cache()
        boundary_mask = bm.prefill_boundary_prediction_forward(
            byte_input_ids, expanded_input_ids=expanded, sequence_start_indices=sequence_start_indices)
        enc.prepare_inference_cache(1)
        dec.prepare_inference_cache(1)
        boundary_mask = boundary_mask[:, :-1]
        forced_id = byte_input_ids[:, -1].cpu().tolist()[0]
        byte_input_ids = byte_input_ids[:, :-1]
        sequence_start_indices = (byte_input_ids == pad).sum(-1)
        boundary_state = MaskState(boundary_mask[:, -1].clone())
        pad_state = MaskState(torch.zeros(1, dtype=torch.bool, device=dev))
        history = byte_input_ids[0].tolist()
        tokens = [0] * (stop_len + 2)  # preallocated output (atoms after the prompt's first L-2 bytes)
        tokens[0] = history[-1]
        n_tok = 1

        expanded_first = torch.tensor(tk.expand_byte_ids(history, n_last=len(history)), device=dev,
                                      dtype=torch.long)[None]
        out = model.forward(byte_input_ids, expanded_input_ids=expanded_first, boundary_mask=boundary_mask,
                            boundary_state=boundary_state, pad_state=pad_state,
                            sequence_start_indices=sequence_start_indices, logits_to_keep=1, use_cache=True,
                            past_key_values=None)
        logits = out.logits
        no_b = logits[0, 0, forced_id].item()
        b = logits[0, 0, forced_id + boundary_offset].item()
        logits[0, 0, :] = -100_000
        logits[0, 0, forced_id] = no_b
        logits[0, 0, forced_id + boundary_offset] = b
        raw = int(torch.argmax(logits[:, -1], dim=-1).item())
        # ---- first token (appended like the original: stripped of the boundary flag) ------
        def strip(r: int) -> int:
            return r - boundary_offset if r >= boundary_offset else r

        tokens[n_tok] = strip(raw)
        n_tok += 1
        finished = raw in (eos, eos + boundary_offset) or n_tok >= stop_len

        if not finished:
            # load the post-prefill state into the static buffers (once per generation)
            for ls, bufs in zip(enc.layer_states, loop.enc_states):
                for dst, src in zip(bufs, ls["xlstm"]["state"]):
                    dst.copy_(src)
            for ls, bufs in zip(dec.layer_states, loop.dec_states):
                for dst, src in zip(bufs, ls["xlstm"]["state"]):
                    dst.copy_(src)
            loop.last_value.copy_(dec.last_value)
            glob.load_prefill(out.past_key_values)

            state = 0
            for h in history:
                state, _ = automaton.step(state, h)
            state, sub = automaton.step(state, raw)
            step_i = 0
            run = runner.run
            while True:
                boundary = raw >= boundary_offset
                if raw == bpe_end:
                    raise OptimizeError("model produced <bpe_token_end>; unsupported at batch 1")
                ids_np[0] = strip(raw)
                ids_np[1] = sub
                pieces.ids.copy_(pinned_ids, non_blocking=True)
                run("enc_m")
                if boundary:
                    run("glob")
                    run("dec_p")
                else:
                    run("dec_n")
                pinned_tok.copy_(pieces.tok, non_blocking=True)
                done.record()
                done.synchronize()  # the single sync of this byte
                raw = int(tok_np[0])
                tokens[n_tok] = strip(raw)
                n_tok += 1
                if debug is not None:
                    debug(step_i, {"raw": raw, "sub": sub, "loop": loop, "glob": glob})
                step_i += 1
                if raw in (eos, eos + boundary_offset) or n_tok >= stop_len:
                    break
                state, sub = automaton.step(state, raw)

        gen = torch.tensor(tokens[:n_tok], dtype=torch.long, device=dev)
        return torch.cat([byte_input_ids[0, :-1], gen]).unsqueeze(0)

    return generate
